import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult

def extract_layout_from_document(document_url: str = None, file_path: str = None):
    """
    Extracts layout elements like paragraphs and tables from a document
    using Azure AI Document Intelligence.

    Args:
        document_url (str, optional): The URL of the document to analyze.
        file_path (str, optional): The local path to the document to analyze.

    Returns:
        dict: A dictionary containing lists of extracted paragraphs and tables,
              or None if an error occurs.
    """
    if not document_url and not file_path:
        raise ValueError("Either document_url or file_path must be provided.")

    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise EnvironmentError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY "
            "environment variables must be set."
        )

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    if file_path:
        with open(file_path, "rb") as f:
            poller = document_intelligence_client.begin_analyze_document(
                "prebuilt-layout", analyze_request=f, content_type="application/octet-stream"
            )
    else: # document_url
         poller = document_intelligence_client.begin_analyze_document(
                "prebuilt-layout", {"urlSource": document_url}
            )

    result: AnalyzeResult = poller.result()

    extracted_data = {
        "paragraphs": [],
        "tables": [],
    }

    if result.paragraphs:
        for paragraph in result.paragraphs:
            extracted_data["paragraphs"].append({
                "role": paragraph.role,
                "content": paragraph.content,
                "bounding_regions": [
                    {
                        "page_number": region.page_number,
                        "polygon": region.polygon
                    } for region in paragraph.bounding_regions
                ]
            })

    if result.tables:
        for table in result.tables:
            # Initialize a grid based on table dimensions
            table_grid = [["" for _ in range(table.column_count)] for _ in range(table.row_count)]

            # Populate the grid with cell content
            for cell in table.cells:
                # This places the content in the top-left corner of the cell's area
                table_grid[cell.row_index][cell.column_index] = cell.content

            extracted_data["tables"].append({
                "row_count": table.row_count,
                "column_count": table.column_count,
                "cells": table_grid,
                 "bounding_regions": [
                    {
                        "page_number": region.page_number,
                        "polygon": region.polygon
                    } for region in table.bounding_regions
                ]
            })

    return extracted_data
